print("Edition: signature")
docs = {"d1": [1, 0, 1], "d2": [1, 1, 0], "d3": [0, 0, 1], "d4": [1, 1, 1]}
query = [1, 1, 0]
def bucket(v):
    return sum(v) % 2
cands = [k for k, v in docs.items() if bucket(v) == bucket(query)]
def score(v):
    return sum(a * b for a, b in zip(v, query))
exact = max(docs, key=lambda k: score(docs[k]))
print("candidate bucket:", cands)
print("best in bucket:", max(cands, key=lambda k: score(docs[k])), "exact best:", exact)
print("RESULT bucket retrieval plus exact re-ranking over candidates")
